from dataclasses import dataclass
from enum import Enum

class CaptchaServiceType(Enum):
    TWO_CAPTCHA = "2captcha"
    ANTI_CAPTCHA = "anti-captcha"

@dataclass
class CaptchaSolution:
    """Represents a solved CAPTCHA"""
