        """Check CAPTCHA solving result"""
        response = self._make_request(
            'POST',
            f'{self.BASE_URL}/getTaskResult',
            json={
                'clientKey': self.api_key,
                'taskId': task_id
            }
        )

        if response.get('errorId') == 0:
            status = 1 if response.get('status') == 'ready' else 0
            solution = response.get('solution', {}).get('gRecaptchaResponse', '')
            cost = response.get('cost', None)
            return {
                'status': status,
                'request': solution,
                'cost': cost
            }
        else:
            return {
                'status': 0,
                'request': response.get('errorDescription', 'ERROR')
            }

    def _poll_for_result(self, task_id: str, polling_interval: float = 5, max_wait_time: int = 300) -> Dict[str, Any]:
        """Poll for CAPTCHA solving result"""
        start_time = time.time()
        while time.time() - start_time < max_wait_time:
            result = self._check_result(task_id)
            if result.get('status') == 1 and result.get('request'):
                return result
            elif result.get('status') == 0 and 'ERROR' not in result.get('request', ''):
                raise CaptchaSolverError(f"CAPTCHA solving failed: {result.get('request')}")

            time.sleep(polling_interval)

        raise CaptchaSolverTimeoutError("CAPTCHA solving timed out")"}

