            "reloadconfig": {
                "handler": self._handle_reload_config,
                "aliases": ["rl"],
                "help": "Reload all settings from config.ini.",
            },
            "restart": {
                "handler": self.watcher.restart,
                "aliases": [],
                "help": "Restart the entire script.",
            },
            "notifytest": {
                "handler": self.watcher.run_notify_test,
                "aliases": ["nt"],
